import { test, expect } from '@playwright/test';

test.describe('Icon Button Accessibility Names', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should assign accessible names to all icon buttons', async ({ page }) => {
    // Verify the home icon button has an accessible name
    const homeButton = page.getByRole('button', { name: /home/i });
    await expect(homeButton).toBeVisible();
    await expect(homeButton).toHaveAttribute('aria-label', /home/i);

    // Verify the search icon button has an accessible name
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();
    await expect(searchButton).toHaveAttribute('aria-label', /search/i);

    // Verify the settings icon button has an accessible name
    const settingsButton = page.getByRole('button', { name: /settings/i });
    await expect(settingsButton).toBeVisible();
    await expect(settingsButton).toHaveAttribute('aria-label', /settings/i);

    // Verify the profile icon button has an accessible name
    const profileButton = page.getByRole('button', { name: /profile/i });
    await expect(profileButton).toBeVisible();
    await expect(profileButton).toHaveAttribute('aria-label', /profile/i);

    // Verify the notifications icon button has an accessible name
    const notificationsButton = page.getByRole('button', { name: /notifications/i });
    await expect(notificationsButton).toBeVisible();
    await expect(notificationsButton).toHaveAttribute('aria-label', /notifications/i);
  });

  test('should handle icon buttons with complex accessible names', async ({ page }) => {
    // Verify the help icon button has a descriptive accessible name
    const helpButton = page.getByRole('button', { name: /help/i });
    await expect(helpButton).toBeVisible();
    await expect(helpButton).toHaveAttribute('aria-label', /get help/i);

    // Verify the logout icon button has a clear accessible name
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();
    await expect(logoutButton).toHaveAttribute('aria-label', /log out of account/i);

    // Verify the email icon button has a descriptive accessible name
    const emailButton = page.getByRole('button', { name: /email/i });
    await expect(emailButton).toBeVisible();
    await expect(emailButton).toHaveAttribute('aria-label', /send email to support/i);

    // Verify the message icon button has a descriptive accessible name
    const messageButton = page.getByRole('button', { name: /message/i });
    await expect(messageButton).toBeVisible();
    await expect(messageButton).toHaveAttribute('aria-label', /view messages/i);
  });
});
